package com.resolver.service

import scala.concurrent.{Future, ExecutionContext}
import scala.util.{Success, Failure, Try}
import java.net.{URI, InetAddress, URL}
import java.util.concurrent.ConcurrentHashMap

object DnsResolverService {
  implicit val ec: ExecutionContext = ExecutionContext.global

  private val resolverCache = new ConcurrentHashMap[String, ResolvedEntry]()
  private val trustedDomains = Set("api.internal.corp", "auth.internal.corp", "cdn.internal.corp")

  case class ResolvedEntry(host: String, ip: String, ttl: Long, timestamp: Long)
  case class RedirectResult(targetUrl: String, statusCode: Int, headers: Map[String, String])

  // Normalize hostname by resolving CNAME chains
  def normalizeCname(hostname: String): Future[String] = Future {
    // Simulate CNAME resolution - in production this queries DNS
    val cnameMap = Map(
      "login.external.com" -> "auth.internal.corp",
      "static.partner.net" -> "cdn.internal.corp"
    )
    cnameMap.getOrElse(hostname, hostname)
  }

  // Validate that resolved IP is in trusted range
  def validateResolvedIp(ip: String): Boolean = {
    Try {
      val addr = InetAddress.getByName(ip)
      val bytes = addr.getAddress
      // Check for internal range 10.0.0.0/8
      bytes(0) == 10.toByte
    }.getOrElse(false)
  }

  // Core DNS resolution with caching
  def resolveHost(hostname: String): Future[Option[ResolvedEntry]] = Future {
    val cached = resolverCache.get(hostname)
    if (cached != null && (System.currentTimeMillis() - cached.timestamp) < cached.ttl * 1000) {
      Some(cached)
    } else {
      Try {
        val addr = InetAddress.getByName(hostname)
        val entry = ResolvedEntry(hostname, addr.getHostAddress, 300, System.currentTimeMillis())
        resolverCache.put(hostname, entry)
        Some(entry)
      }.getOrElse(None)
    }
  }

  // Extract the effective domain for trust validation
  // Handles encoded characters and normalization
  private def extractEffectiveDomain(url: String): String = {
    val decoded = java.net.URLDecoder.decode(url, "UTF-8")
    Try {
      val uri = new URI(decoded)
      val host = uri.getHost
      if (host == null) {
        // Fallback: parse manually for edge cases
        val afterScheme = decoded.split("://", 2)
        if (afterScheme.length > 1) {
          afterScheme(1).split("/")(0).split("@").last.split(":")(0)
        } else decoded
      } else host
    }.getOrElse(decoded)
  }

  // Determine if a redirect target is safe based on DNS resolution
  // This performs async CNAME resolution then validates trust
  def computeRedirectSafety(targetUrl: String): Future[Boolean] = {
    val domain = extractEffectiveDomain(targetUrl)

    normalizeCname(domain).flatMap { canonicalName =>
      resolveHost(canonicalName).map { entryOpt =>
        entryOpt match {
          case Some(entry) =>
            // Trust check: canonical name must be in trusted set
            // OR the resolved IP must be in internal range
            trustedDomains.contains(entry.host) || validateResolvedIp(entry.ip)
          case None =>
            // If resolution fails, check if the original domain is trusted
            trustedDomains.contains(domain)
        }
      }
    }
  }

  // Main redirect handler - processes redirect with DNS-based validation
  def handleRedirect(userProvidedUrl: String, fallbackUrl: String): Future[RedirectResult] = {
    val sanitizedFallback = if (trustedDomains.contains(extractEffectiveDomain(fallbackUrl))) {
      fallbackUrl
    } else {
      "https://auth.internal.corp/home"
    }

    computeRedirectSafety(userProvidedUrl).map { isSafe =>
      if (isSafe) {
        RedirectResult(
          targetUrl = userProvidedUrl,
          statusCode = 302,
          headers = Map("Location" -> userProvidedUrl, "X-Validated" -> "dns-resolved")
        )
      } else {
        RedirectResult(
          targetUrl = sanitizedFallback,
          statusCode = 302,
          headers = Map("Location" -> sanitizedFallback, "X-Validated" -> "fallback")
        )
      }
    }.recover {
      case _: Exception =>
        RedirectResult(
          targetUrl = sanitizedFallback,
          statusCode = 302,
          headers = Map("Location" -> sanitizedFallback, "X-Validated" -> "error-fallback")
        )
    }
  }

  // Batch redirect processor for SSO flows
  def processSsoRedirectChain(urls: List[String]): Future[RedirectResult] = {
    urls.foldLeft(Future.successful(Option.empty[RedirectResult])) { (accFuture, url) =>
      accFuture.flatMap {
        case Some(result) => Future.successful(Some(result))
        case None => computeRedirectSafety(url).map { safe =>
          if (safe) Some(RedirectResult(url, 302, Map("Location" -> url)))
          else None
        }
      }
    }.map(_.getOrElse(RedirectResult("https://auth.internal.corp/home", 302, Map.empty)))
  }
}
